12	struct UserProfileScreen: View {
13	    @Bindable var context: UserProfileScreenViewModel.Context
14	    
15	    var body: some View {
16	        Form {
17	            headerSection
18	        }
19	        .compoundList()
20	        .navigationTitle(L10n.screenRoomMemberDetailsTitle)
21	        .navigationBarTitleDisplayMode(.inline)
22	        .toolbar { toolbar }
23	        .alert(item: $context.alertInfo)
24	        .sheet(item: $context.inviteConfirmationUser) { user in
25	            SendInviteConfirmationView(userToInvite: user,
26	                                       mediaProvider: context.mediaProvider) {
27	                context.send(viewAction: .createDirectChat)
28	            }
29	        }
30	        .track(screen: .User)
31	        .interactiveQuickLook(item: $context.mediaPreviewItem, allowEditing: false)
32	    }
33	    
34	    // MARK: - Private
35	    
36	    @ViewBuilder
37	    private var headerSection: some View {
38	        if let userProfile = context.viewState.userProfile {
39	            AvatarHeaderView(user: userProfile,
40	                             isVerified: context.viewState.showVerifiedBadge,
41	                             avatarSize: .user(on: .memberDetails),
42	                             mediaProvider: context.mediaProvider) { url in
43	                context.send(viewAction: .displayAvatar(url))
44	            } footer: {
45	                otherUserFooter
46	            }
47	        } else {
48	            AvatarHeaderView(user: UserProfileProxy(userID: context.viewState.userID),
49	                             isVerified: context.viewState.showVerifiedBadge,
50	                             avatarSize: .user(on: .memberDetails),
51	                             mediaProvider: context.mediaProvider) { }
52	        }
53	    }
54	    
55	    private var otherUserFooter: some View {
56	        HStack(spacing: 8) {
57	            if context.viewState.userProfile != nil, !context.viewState.isOwnUser {
58	                Button {
59	                    context.send(viewAction: .openDirectChat)
60	                } label: {
61	                    CompoundIcon(\.chat)
62	                }
63	                .buttonStyle(FormActionButtonStyle(title: L10n.commonMessage))
64	                .accessibilityIdentifier(A11yIdentifiers.roomMemberDetailsScreen.directChat)
65	            }
66	            
67	            if let roomID = context.viewState.dmRoomID {
68	                Button {
69	                    context.send(viewAction: .startCall(roomID: roomID))
70	                } label: {
71	                    CompoundIcon(\.videoCall)
72	                }
73	                .buttonStyle(FormActionButtonStyle(title: L10n.actionCall))
74	            }
75	            
76	            if let permalink = context.viewState.permalink {
77	                ShareLink(item: permalink) {
78	                    CompoundIcon(\.shareIos)
79	                }
80	                .buttonStyle(FormActionButtonStyle(title: L10n.actionShare))
81	            }
82	        }
83	        .padding(.top, 32)
84	    }
85	        
86	    @ToolbarContentBuilder
87	    private var toolbar: some ToolbarContent {
88	        if context.viewState.isPresentedModally {
89	            ToolbarItem(placement: .confirmationAction) {
90	                Button(L10n.actionDone) {
91	                    context.send(viewAction: .dismiss)
92	                }
93	            }
94	        }
95	    }
96	}
