100	struct UserProfileScreen_Previews: PreviewProvider, TestablePreview {
101	    static let verifiedUserViewModel = makeViewModel(userID: RoomMemberProxyMock.mockDan.userID)
102	    static let otherUserViewModel = makeViewModel(userID: RoomMemberProxyMock.mockAlice.userID)
103	    static let accountOwnerViewModel = makeViewModel(userID: RoomMemberProxyMock.mockMe.userID)
104	    
105	    static var previews: some View {
106	        UserProfileScreen(context: verifiedUserViewModel.context)
107	            .snapshotPreferences(expect: verifiedUserViewModel.context.observe(\.viewState.isVerified).map { $0 != nil })
108	            .previewDisplayName("Verified User")
109	        
110	        UserProfileScreen(context: otherUserViewModel.context)
111	            .snapshotPreferences(expect: otherUserViewModel.context.observe(\.viewState.isVerified).map { $0 != nil })
112	            .previewDisplayName("Other User")
113	        
114	        UserProfileScreen(context: accountOwnerViewModel.context)
115	            .snapshotPreferences(expect: accountOwnerViewModel.context.observe(\.viewState.isVerified).map { $0 != nil })
116	            .previewDisplayName("Account Owner")
117	    }
118	    
119	    static func makeViewModel(userID: String) -> UserProfileScreenViewModel {
120	        let clientProxyMock = ClientProxyMock(.init())
121	        
122	        clientProxyMock.userIdentityForFallBackToServerClosure = { userID, _ in
123	            let identity = switch userID {
124	            case RoomMemberProxyMock.mockDan.userID:
125	                UserIdentityProxyMock(configuration: .init(verificationState: .verified))
126	            default:
127	                UserIdentityProxyMock(configuration: .init())
128	            }
129	            
130	            return .success(identity)
131	        }
132	
133	        if userID != RoomMemberProxyMock.mockMe.userID {
134	            clientProxyMock.directRoomForUserIDReturnValue = .success("roomID")
135	        }
136	        
137	        return UserProfileScreenViewModel(userID: userID,
138	                                          isPresentedModally: false,
139	                                          userSession: UserSessionMock(.init(clientProxy: clientProxyMock)),
140	                                          userIndicatorController: ServiceLocator.shared.userIndicatorController,
141	                                          analytics: ServiceLocator.shared.analytics)
142	    }
143	}
