11	struct LoadableAvatarImage: View {
12	    enum Shape {
13	        case circle
14	        case roundedRect
15	    }
16	    
17	    private let url: URL?
18	    private let name: String?
19	    private let contentID: String
20	    private let shape: Shape
21	    private let avatarSize: Avatars.Size
22	    private let mediaProvider: MediaProviderProtocol?
23	    private let onTap: ((URL) -> Void)?
24	    
25	    @ScaledMetric private var frameSize: CGFloat
26	    
27	    init(url: URL?,
28	         name: String?,
29	         contentID: String,
30	         shape: LoadableAvatarImage.Shape = .circle,
31	         avatarSize: Avatars.Size,
32	         mediaProvider: MediaProviderProtocol?,
33	         onTap: ((URL) -> Void)? = nil) {
34	        self.url = url
35	        self.name = name
36	        self.contentID = contentID
37	        self.shape = shape
38	        self.avatarSize = avatarSize
39	        self.mediaProvider = mediaProvider
40	        self.onTap = onTap
41	        
42	        _frameSize = ScaledMetric(wrappedValue: avatarSize.value)
43	    }
44	    
45	    var body: some View {
46	        if let onTap, let url {
47	            Button {
48	                onTap(url)
49	            } label: {
50	                clippedAvatar
51	            }
52	            .buttonStyle(.borderless) // Add a button style to stop the whole row being tappable.
53	        } else {
54	            clippedAvatar
55	        }
56	    }
57	    
58	    private var clippedAvatar: some View {
59	        avatar
60	            .frame(width: frameSize, height: frameSize)
61	            .background(Color.compound.bgCanvasDefault)
62	            .avatarShape(shape, scaledSize: _frameSize)
63	            .environment(\.shouldAutomaticallyLoadImages, true) // We always load avatars.
64	    }
65	    
66	    @ViewBuilder
67	    private var avatar: some View {
68	        if let url {
69	            LoadableImage(url: url,
70	                          mediaType: .avatar,
71	                          size: avatarSize.scaledSize,
72	                          mediaProvider: mediaProvider) { image in
73	                image
74	                    .scaledToFill()
75	            } placeholder: {
76	                PlaceholderAvatarImage(name: name, contentID: contentID)
77	            }
78	        } else {
79	            PlaceholderAvatarImage(name: name, contentID: contentID)
80	        }
81	    }
82	}
83	
84	extension View {
85	    func avatarShape(_ shape: LoadableAvatarImage.Shape, size: CGFloat) -> some View {
86	        modifier(AvatarShapeModifier(shape: shape, size: size))
87	    }
88	    
89	    func avatarShape(_ shape: LoadableAvatarImage.Shape, scaledSize: ScaledMetric<CGFloat>) -> some View {
90	        modifier(AvatarShapeModifier(shape: shape, scaledSize: scaledSize))
91	    }
92	}
93	
94	private struct AvatarShapeModifier: ViewModifier {
95	    private let shape: LoadableAvatarImage.Shape
96	    @ScaledMetric private var scaledSize: CGFloat
97	    
98	    init(shape: LoadableAvatarImage.Shape, size: CGFloat) {
99	        self.shape = shape
100	        _scaledSize = ScaledMetric(wrappedValue: size)
101	    }
102	    
103	    init(shape: LoadableAvatarImage.Shape, scaledSize: ScaledMetric<CGFloat>) {
104	        self.shape = shape
105	        _scaledSize = scaledSize
106	    }
107	    
108	    func body(content: Content) -> some View {
109	        switch shape {
110	        case .circle:
111	            content.clipShape(Circle())
112	        case .roundedRect:
113	            let shape = RoundedRectangle(cornerRadius: scaledSize / 4)
114	            content
115	                .clipShape(shape)
116	                .overlay(shape.stroke(.compound.iconQuaternaryAlpha, lineWidth: 1))
117	        }
118	    }
119	}
