101	    private func displayFullScreenAvatar(_ url: URL) async {
102	        guard let userProfile = state.userProfile else { fatalError() }
103	        
104	        showLoadingIndicator(allowsInteraction: false)
105	        defer { hideLoadingIndicator() }
106	        
107	        // We don't actually know the mime type here, assume it's an image.
108	        if let mediaSource = try? MediaSourceProxy(url: url, mimeType: "image/jpeg"),
109	           case let .success(file) = await userSession.mediaProvider.loadFileFromSource(mediaSource) {
110	            state.bindings.mediaPreviewItem = MediaPreviewItem(file: file, title: userProfile.displayName)
111	        }
112	    }
113	    
114	    private func openDirectChat() {
115	        guard let userProfile = state.userProfile else { fatalError() }
116	        
117	        showLoadingIndicator(allowsInteraction: false)
118	        defer { hideLoadingIndicator() }
119	        
120	        switch userSession.clientProxy.directRoomForUserID(userProfile.userID) {
121	        case .success(let roomID):
122	            if let roomID {
123	                actionsSubject.send(.openDirectChat(roomID: roomID))
124	            } else {
125	                state.bindings.inviteConfirmationUser = userProfile
126	            }
127	        case .failure:
128	            state.bindings.alertInfo = .init(id: .failedOpeningDirectChat)
129	        }
130	    }
131	    
132	    private func createDirectChat() async {
133	        guard let userProfile = state.userProfile else { fatalError() }
134	        
135	        showLoadingIndicator(allowsInteraction: false)
136	        defer { hideLoadingIndicator() }
137	        
138	        switch await userSession.clientProxy.createDirectRoom(with: userProfile.userID, expectedRoomName: userProfile.displayName) {
139	        case .success(let roomID):
140	            analytics.trackCreatedRoom(isDM: true)
141	            actionsSubject.send(.openDirectChat(roomID: roomID))
142	        case .failure:
143	            state.bindings.alertInfo = .init(id: .failedOpeningDirectChat)
144	        }
145	    }
146	    
147	    private func startCall(roomID: String) async {
148	        guard case let .joined(roomProxy) = await userSession.clientProxy.roomForIdentifier(roomID) else {
149	            showErrorIndicator()
150	            return
151	        }
152	        actionsSubject.send(.startCall(roomProxy: roomProxy))
153	    }
